('rowid-2627','GHBC-REQ-002627','GS 1207:2018',4,'4.9','4.9.2','GHBC-C-001025','The room shall have a floor area of not less than 80 square feet (7.44 m2 ) for a single machine and not less than 3.7 m2 (40 square feet) for each additional machine.','mandatory',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":80,"unit":null,"operator":"not less than","context":"om shall have a floor area of not less than 80 square feet (7.44 m2 ) for a "},{"parameter":"comparison","value":3.7,"unit":null,"operator":"not less than","context":"m2 ) for a single machine and not less than 3.7 m2 (40 square feet) for each "},{"parameter":"measurement","value":80,"unit":"s","operator":null,"context":"a floor area of not less than 80 square feet (7.44 m2 ) for a si"},{"parameter":"measurement","value":7.44,"unit":"m2","operator":null,"context":"not less than 80 square feet (7.44 m2 ) for a single machine and no"},{"parameter":"measurement","value":3.7,"unit":"m2","operator":null,"context":"gle machine and not less than 3.7 m2 (40 square feet) for each add"},{"parameter":"measurement","value":40,"unit":"s","operator":null,"context":"ine and not less than 3.7 m2 (40 square feet) for each additiona"}]','[]',0.93,'extracted','VERIFIED','2018','df3e36b0c390a29c6d84e5b82818026e7f9838dac9ea168291f392040a03bc82','2026-08-15 13:56:12'),
