INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-2851','GHBC-REQ-002851','GS 1207:2018',4,'4.9','4.12.4.1','GHBC-C-001100','A hangar shall not be attached to a dwelling unless separated by a fire barrier having a fireresistance rating of not less than 1 hour.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"comparison","value":1,"unit":null,"operator":"not less than","context":"ng a fireresistance rating of not less than 1 hour."},{"parameter":"measurement","value":1,"unit":"h","operator":null,"context":"tance rating of not less than 1 hour."}]','[]',0.93,'requires_review','DRAFT','2018','31ac670572d68115446f860cf03b297a5185bc6f6a3fe3a7a8ae5e70eeb5f073','2026-08-15 13:56:12'),
