INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-5551','GHBC-REQ-005551','GS 1207:2018',8,'8.9','8.9.3','GHBC-C-001829','A 1-hour fire-resistance rating is required for smoke barriers.','fire',NULL,NULL,NULL,NULL,'["Smoke barriers constructed of minimum 2.5 mm (0.10-inch-thick) steel in Group I-3 buildings."]','[]','[]',0.9,'extracted','VERIFIED','2018','beb27eeea3b888f0e391e941e052bbfc89d5cb9d37f43b5bc0f9fb282aafdc91','2026-08-15 13:56:12'),
('rowid-5552','GHBC-REQ-005552','GS 1207:2018',8,'8.9','8.9.3','GHBC-C-001829','EXCEPTIONS: Smoke barriers constructed of minimum 2.5 mm (0.10-inch-thick) steel in Group I-3 buildings.','fire',NULL,NULL,NULL,NULL,'["Smoke barriers constructed of minimum 2.5 mm (0.10-inch-thick) steel in Group I-3 buildings."]','[{"parameter":"measurement","value":2.5,"unit":"mm","operator":null,"context":"rriers constructed of minimum 2.5 mm (0.10-inch-thick) steel in Gr"}]','[]',0.93,'extracted','VERIFIED','2018','69be7fd55baf147fa1155f12495d78e0723a64ed18e2dc2e6febe4c6860f5e58','2026-08-15 13:56:12'),
('rowid-5553','GHBC-REQ-005553','GS 1207:2018',8,'8.9','8.9.4','GHBC-C-001830','Smoke barriers shall form an effective membrane continuous from the top of the foundation or floor/ceiling assembly below to the underside of the floor or roof sheathing, deck or slab above, including continuity through concealed spaces, such as those found above suspended ceilings, and interstitial structural and mechanical spaces.','fire',NULL,NULL,NULL,NULL,'[" Smoke-barrier walls are not required in interstitial spaces where such spaces are designed and constructed with ceilings or exterior walls that provide resistance to the passage of fire and smoke equivalent to that provided by the smoke-barrier walls."]','[]','[]',0.9,'extracted','VERIFIED','2018','8b54e784a0a1ec9ff514335260d3642fa5183a5e96d8a5aee1fe67f3560c2229','2026-08-15 13:56:12'),
('rowid-5554','GHBC-REQ-005554','GS 1207:2018',8,'8.9','8.9.4','GHBC-C-001830','The supporting construction shall be protected to afford the required fire-resistance rating of the wall or floor supported in buildings of other than Type IB, IIB or IVB construction.','fire',NULL,NULL,NULL,NULL,'[" Smoke-barrier walls are not required in interstitial spaces where such spaces are designed and constructed with ceilings or exterior walls that provide resistance to the passage of fire and smoke equivalent to that provided by the smoke-barrier walls."]','[]','[]',0.9,'extracted','VERIFIED','2018','dff2123866d384e8f6dec97a2fc24775041d54480d52d8a3cab5a494050844fd','2026-08-15 13:56:12'),
('rowid-5555','GHBC-REQ-005555','GS 1207:2018',8,'8.9','8.9.4','GHBC-C-001830','Smoke barrier walls used to separate smoke compartments shall comply with Clause 8.9.4.1.','fire',NULL,NULL,NULL,NULL,'[" Smoke-barrier walls are not required in interstitial spaces where such spaces are designed and constructed with ceilings or exterior walls that provide resistance to the passage of fire and smoke equivalent to that provided by the smoke-barrier walls."]','[]','[]',0.9,'extracted','VERIFIED','2018','1668a7bc1b64b1fc4acf10744e7adb4476e3d008b563d1db5a14b706cd092f05','2026-08-15 13:56:12'),
