INSERT OR IGNORE INTO "requirements" ("id", "requirement_id", "source_document", "part", "section", "clause", "clause_id", "source_text", "requirement_type", "subject", "condition", "action", "object", "exceptions", "parameters_json", "references_json", "confidence", "verification_status", "editorial_state", "effective_date", "content_hash", "created_at") VALUES ('rowid-9651','GHBC-REQ-009651','GS 1207:2018',11,'11.10','11.10.1.9.7','GHBC-C-002856','Items 1 through 4 shall not apply to doors to areas occupied by persons who, because of clinical needs, require restraint or containment as part of the function of a psychiatric treatment area.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":4,"unit":"s","operator":null,"context":"Items 1 through 4 shall not apply to doors to are"}]','[]',0.93,'requires_review','DRAFT','2018','4c3bef807995ab0b2b18e8f44f118c5d94f471d79bba42376f3924fed3ee2783','2026-08-15 13:56:13'),
('rowid-9652','GHBC-REQ-009652','GS 1207:2018',11,'11.10','11.10.1.9.7','GHBC-C-002856','2.','informational',NULL,NULL,NULL,NULL,'[]','[]','[]',0.9,'extracted','VERIFIED','2018','7f5c1c475e1708c3ba1a2a97f34cc2bf95b6a598a3944472bd44ea0c3a1b8ef2','2026-08-15 13:56:13'),
('rowid-9653','GHBC-REQ-009653','GS 1207:2018',11,'11.10','11.10.1.9.7','GHBC-C-002856','Items 1 through 4 shall not apply to doors to areas where a listed Escape control system is utilized to reduce the risk of child abduction from nursery and obstetric areas of a Group I-2 hospital.','prohibited',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":4,"unit":"s","operator":null,"context":"Items 1 through 4 shall not apply to doors to are"},{"parameter":"measurement","value":-2,"unit":"h","operator":null,"context":"d obstetric areas of a Group I-2 hospital."}]','[]',0.93,'requires_review','DRAFT','2018','e1d12c96b2143ba2adc7e03b2bd5adc697633bcd62af3f013417cafb744897e4','2026-08-15 13:56:13'),
('rowid-9654','GHBC-REQ-009654','GS 1207:2018',11,'11.10','11.10.1.9.8','GHBC-C-002857','Delayed Escape locking systems shall be permitted to be installed on doors serving the following occupancies in buildings that are equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1 or an approved automatic smoke or heat detection system installed in accordance with Clause 10.7.','fire',NULL,NULL,NULL,NULL,'["Delayed Escape locking systems shall be permitted to be installed on exit or exit access doors, other than the main exit or exit access door, serving a courtroom in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. 11.10.1.9.8.1 Delayed Escape locking system. The delayed escape locking system shall be installed and operated in accordance with all of the following: 1. The delay electronics of the delayed escape locking system shall deactivate upon actuation of the automatic sprinkler system or automatic fire detection system, allowing immediate free escape. 2. The delay electronics of the delayed escape locking system shall deactivate upon loss of power controlling the lock or lock mechanism, allowing immediate free Escape. 3. The delayed escape locking system shall have the capability of being deactivated at the fire command center and other approved locations.","Where approved, a delay of not more than 30 seconds is permitted on a delayed Escape door. 5. The Escape path from any point shall not pass through more than one delayed Escape locking system.","Where approved, in Group I occupancies, the installation of a sign is not required where care recipients who because of clinical needs require restraint or containment as part of the function of the treatment area. 7. Emergency lighting shall be provided on the escape side of the door. 8. The delayed Escape locking system units shall be listed in accordance with this Code."]','[]','[]',0.9,'extracted','VERIFIED','2018','d180c9168f0499ac68f9c72706f961d88371834f8a50a88b2988f24c476ae1f0','2026-08-15 13:56:13'),
('rowid-9655','GHBC-REQ-009655','GS 1207:2018',11,'11.10','11.10.1.9.8','GHBC-C-002857','1.','informational',NULL,NULL,NULL,NULL,'["Delayed Escape locking systems shall be permitted to be installed on exit or exit access doors, other than the main exit or exit access door, serving a courtroom in buildings equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1. 11.10.1.9.8.1 Delayed Escape locking system. The delayed escape locking system shall be installed and operated in accordance with all of the following: 1. The delay electronics of the delayed escape locking system shall deactivate upon actuation of the automatic sprinkler system or automatic fire detection system, allowing immediate free escape. 2. The delay electronics of the delayed escape locking system shall deactivate upon loss of power controlling the lock or lock mechanism, allowing immediate free Escape. 3. The delayed escape locking system shall have the capability of being deactivated at the fire command center and other approved locations.","Where approved, a delay of not more than 30 seconds is permitted on a delayed Escape door. 5. The Escape path from any point shall not pass through more than one delayed Escape locking system.","Where approved, in Group I occupancies, the installation of a sign is not required where care recipients who because of clinical needs require restraint or containment as part of the function of the treatment area. 7. Emergency lighting shall be provided on the escape side of the door. 8. The delayed Escape locking system units shall be listed in accordance with this Code."]','[]','[]',0.9,'extracted','VERIFIED','2018','fbd36ac47d25a056f6e386abd3db9ab5d119ea59eb9908004c04ae9272844518','2026-08-15 13:56:13'),
