('rowid-9686','GHBC-REQ-009686','GS 1207:2018',11,'11.10','11.10.1.9.9','GHBC-C-002858','The doors shall be arranged to unlock from a manual unlocking device located 11.16 mm to 1219 mm (40 inches to 48 inches) vertically above the floor and within 1524 mm (5 feet) of the secured doors.','mandatory',NULL,NULL,NULL,NULL,'[]','[{"parameter":"measurement","value":11.16,"unit":"mm","operator":null,"context":"nual unlocking device located 11.16 mm to 1219 mm (40 inches to 48 i"},{"parameter":"measurement","value":1219,"unit":"mm","operator":null,"context":"ng device located 11.16 mm to 1219 mm (40 inches to 48 inches) vert"},{"parameter":"measurement","value":40,"unit":"in","operator":null,"context":" located 11.16 mm to 1219 mm (40 inches to 48 inches) vertically "},{"parameter":"measurement","value":48,"unit":"in","operator":null,"context":"6 mm to 1219 mm (40 inches to 48 inches) vertically above the flo"},{"parameter":"measurement","value":1524,"unit":"mm","operator":null,"context":"ly above the floor and within 1524 mm (5 feet) of the secured doors"},{"parameter":"measurement","value":5,"unit":"feet","operator":null,"context":"the floor and within 1524 mm (5 feet) of the secured doors."}]','[]',0.93,'extracted','VERIFIED','2018','0a91fdcb1757bdfae24167ada14461c69f8bc8a2a20bf77d0ca5215b560208b5','2026-08-15 13:56:13'),
